import {
  createPanZoom,
  type PanZoom as PanZoomController,
  type PanZoomPoint,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createSignal, merge, untrack } from "solid-js";

import { Button } from "./button.tsx";
import { type PartProps } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

export interface PanzoomProps {
  /** The image: a URL, or a `data:` URI. */
  readonly src: string;
  /** The image's text alternative; the viewport's own name is `label`. */
  readonly alt: string;
  /** Its natural width, for the frame's shape; read from the image when both are left out. */
  readonly width?: number;
  /** Its natural height, for the frame's shape; read from the image when both are left out. */
  readonly height?: number;
  /** The viewport's accessible name: what the image shows, in the page's words (default `"Image"`). */
  readonly label?: string;
  /** The line under the frame; left out, the gestures and the keys in one sentence. */
  readonly hint?: string;
  /** Smallest scale, and where reset returns. @default 1 */
  readonly min?: number;
  /** Largest scale. @default 4 */
  readonly max?: number;
  /** The zoom buttons' and `+` / `-`'s increment. @default 0.25 */
  readonly step?: number;
  /** Starting scale when uncontrolled; ignored while `scale` is set. */
  readonly defaultScale?: number;
  /** Controlled: the host owns the scale and this is the only thing that changes it. */
  readonly scale?: number;
  readonly onScaleChange?: (scale: number) => void;
  readonly onPanChange?: (offset: PanZoomPoint) => void;
  /** `"clamp"` (default) keeps the scaled image covering the frame; `"free"` lets it leave. */
  readonly bounds?: "clamp" | "free";
  readonly class?: string;
  /** The primitive, once: a page that reads `scale()` or drives the camera. */
  readonly onReady?: (panzoom: PanZoomController) => void;
}

const DEFAULT_HINT = "Drag to pan, pinch or Ctrl/⌘ + wheel to zoom. Keys: +, -, arrows and 0.";

const rootClass = css.cn(css.display("grid"), css.gap(t.space._2), css.width("100%"));

// The frame is the box the primitive's maths assumes: the image fills it at `min` (object-fit: cover), its origin is the
// centre, and the clips are the rounded corners. `touch-action: none` is the touch drag; the pointer is the only gesture
// the primitive cannot replace with a key, so it is the only one the skin has to allow through.
const viewportClass = css.cn(
  css.position("relative"),
  css.display("block"),
  css.width("100%"),
  css.overflow("hidden"),
  css.boxSizing("border-box"),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.xl),
  css.bg(t.color.surface),
  css.touchAction("none"),
  css.userSelect("none"),
  css.cursor("grab"),
  css.outline("none"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
  css.attr("data-dragging", "true")(css.cursor("grabbing")),
);

// The transform is the primitive's, inline: the transition is the skin's, and only for a reader who allows motion. A drag
// sets `data-dragging` on the image, and the attribute's higher specificity drops the transition while the pointer moves,
// so the picture follows the pointer instead of trailing it.
const imageClass = css.cn(
  css.position("absolute"),
  css.inset("0"),
  css.width("100%"),
  css.height("100%"),
  css.objectFit("cover"),
  css.transformOrigin("50% 50%"),
  css.userSelect("none"),
  css.pointerEvents("none"),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.transition("transform 140ms ease-out"),
    css.attr("data-dragging", "true")(css.transition("none")),
  ),
);

const barClass = css.cn(
  css.display("flex"),
  css.flexWrap("wrap"),
  css.alignItems("center"),
  css.justifyContent("space-between"),
  css.gap(t.space._2),
);

// The live region is visible, not hidden: the zoom is a number a reader may want to read, and a region that is on screen is
// also a region a screen reader has been watching.
const valueClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.fontVariantNumeric("tabular-nums"),
  css.color(t.color.text),
  css.minWidth(t.space._7),
);

const controlsClass = css.cn(css.display("flex"), css.flexWrap("wrap"), css.gap(t.space._2));

const hintClass = css.cn(css.margin("0"), css.fontSize(t.font.sizeSm), css.color(t.color.muted));

/**
 * One image in a frame, styled: `createPanZoom` owns the scale, the offset, the pointer drag and pinch, the wheel, the
 * double click, the keys (+, -, arrows, 0) and the live value the viewport describes; the skin owns the surface and its
 * rounded corners, the focus ring, the value and the three buttons, the hint, and the transition that honours reduced
 * motion.
 *
 * The frame's shape comes from `width` / `height` (or the image's own natural size once it loads), and the image fills it
 * with `object-fit: cover`, which is what the primitive's clamp assumes. A page that needs a letterboxed image passes
 * `bounds="free"`.
 */
export const Panzoom = (props: PanzoomProps): JSX.Element => {
  const panzoom = createPanZoom({
    get min() {
      return props.min;
    },
    get max() {
      return props.max;
    },
    get step() {
      return props.step;
    },
    defaultScale: props.defaultScale,
    get scale() {
      return props.scale;
    },
    get bounds() {
      return props.bounds;
    },
    get onScaleChange() {
      return props.onScaleChange;
    },
    get onPanChange() {
      return props.onPanChange;
    },
    get labels() {
      return props.label === undefined ? undefined : { viewport: props.label };
    },
  });
  // a structural prop, read once: it is the primitive for a page, not a signal
  untrack(() => props.onReady)?.(panzoom);

  // the natural size, until the image has loaded and told us; 16:10 is the shape of a frame with nothing to go on
  const [natural, setNatural] = createSignal({ width: 16, height: 10 });
  const size = () => ({
    width: props.width ?? natural().width,
    height: props.height ?? natural().height,
  });
  const readNatural = (event: Event & { readonly currentTarget: HTMLImageElement }): void => {
    const image = event.currentTarget;
    if (image.naturalWidth > 0 && image.naturalHeight > 0) {
      setNatural({ width: image.naturalWidth, height: image.naturalHeight });
    }
  };

  // The skin's own bit of drag state: the primitive owns the gesture, this only says the pointer is down, for the cursor
  // and for the transition.
  const [dragging, setDragging] = createSignal(false);

  const viewport = merge(panzoom.viewportProps, {
    "data-part": "panzoom-viewport",
    "data-dragging": () => (dragging() ? "true" : undefined),
    get style() {
      const { width, height } = size();
      // kebab-case: Solid's style helper sets every key with `setProperty`, which ignores a camelCase name
      return { "aspect-ratio": `${width} / ${height}` };
    },
    get class() {
      return viewportClass;
    },
    onPointerDown: (event: PointerEvent) => {
      setDragging(true);
      panzoom.viewportProps.onPointerDown(event);
    },
    onPointerUp: (event: PointerEvent) => {
      setDragging(false);
      panzoom.viewportProps.onPointerUp(event);
    },
    onPointerCancel: (event: PointerEvent) => {
      setDragging(false);
      panzoom.viewportProps.onPointerCancel(event);
    },
  } as PartProps);

  const image = merge(panzoom.imageProps, {
    "data-part": "panzoom-image",
    "data-dragging": () => (dragging() ? "true" : undefined),
    get class() {
      return imageClass;
    },
  } as PartProps);

  return (
    <div data-part="panzoom" class={css.cn(rootClass, props.class)}>
      <div {...viewport}>
        <img
          {...image}
          alt={props.alt}
          src={props.src}
          width={size().width}
          height={size().height}
          onLoad={readNatural}
        />
      </div>
      <div data-part="panzoom-bar" class={barClass}>
        <span {...panzoom.valueProps} data-part="panzoom-value" class={valueClass}>
          {panzoom.value()}
        </span>
        <div data-part="panzoom-controls" class={controlsClass}>
          <Button size="sm" tone="quiet" onClick={panzoom.zoomOut}>
            Zoom out
          </Button>
          <Button size="sm" tone="quiet" onClick={panzoom.zoomIn}>
            Zoom in
          </Button>
          <Button size="sm" tone="quiet" onClick={panzoom.reset}>
            Reset
          </Button>
        </div>
      </div>
      <p data-part="panzoom-hint" class={hintClass}>
        {props.hint ?? DEFAULT_HINT}
      </p>
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";

import { Panzoom } from "./panzoom.tsx";

/** The demo's image: a drawn landscape, so the fixture needs no network and no binary in the repository. */
const SCENE = `<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="900" viewBox="0 0 1600 900">
  <defs>
    <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#cfe4f5"/>
      <stop offset="1" stop-color="#f3e3cf"/>
    </linearGradient>
  </defs>
  <rect width="1600" height="900" fill="url(#sky)"/>
  <circle cx="1180" cy="250" r="92" fill="#f4c66a"/>
  <path d="M0 700 L320 430 L640 700 Z" fill="#8fa6a0"/>
  <path d="M420 700 L820 350 L1220 700 Z" fill="#5f7f77"/>
  <path d="M1000 700 L1320 470 L1640 700 Z" fill="#7d968f"/>
  <path d="M0 760 Q400 690 800 740 T1600 730 V900 H0 Z" fill="#3d5a52"/>
</svg>`;

/** The image the demo and its test use, as a `data:` URI. */
export const PANZOOM_IMAGE = `data:image/svg+xml,${encodeURIComponent(SCENE)}`;

/** The image's natural size, which is also the frame's shape. */
export const PANZOOM_WIDTH = 1600;
export const PANZOOM_HEIGHT = 900;

/** The frame's width in the fixture, so the bounds a test reads are whole numbers. */
const FRAME_WIDTH = 480;

/** What a mounted demo hands the test: where it lives and a teardown. */
export interface MountedPanzoom {
  readonly root: HTMLElement;
  readonly dispose: () => void;
}

/**
 * Mounts the styled pan-zoom in ordinary use: a wide landscape in a 480 px frame on the surface, the value and the three
 * controls under it, and the hint that says what the pointer and the keys do. The primitive owns the gestures.
 */
export const mountPanzoom = (): MountedPanzoom => {
  const root = document.createElement("div");
  // the wrapper is the page: a width the frame fills, so the test's geometry does not depend on the browser's viewport
  root.style.width = `${FRAME_WIDTH}px`;
  document.body.append(root);
  const dispose = render(
    () => (
      <Panzoom
        src={PANZOOM_IMAGE}
        alt="A mountain lake at dusk"
        width={PANZOOM_WIDTH}
        height={PANZOOM_HEIGHT}
        label="A mountain lake at dusk"
      />
    ),
    root,
  );
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { afterEach, describe, expect, it } from "vite-plus/test";

import { type MountedPanzoom, mountPanzoom } from "./panzoom.fixture";

// No APG pattern and no Quint spec exists for pan-zoom, so this file is the skin's oracle: it mounts the starter in a real
// Chromium, at a 480 px frame, and drives the same events a reader does. The accessible contract (a focusable named
// viewport, keys for every gesture, a live value) is only observable through the DOM, so nothing here reaches into the
// primitive except through the elements.
//
// The frame is 480 x 270 (the image is 16:9): at scale 1.5 the clamp is (120, 67.5), at 2 it is (240, 135), and an arrow
// step at 24 px is a whole number.

/** Solid 2 applies setters on the next flush, and the transform follows the flush: two frames settle both. */
const settle = (): Promise<void> =>
  new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));

const live: MountedPanzoom[] = [];

const mounted = (): MountedPanzoom => {
  const instance = mountPanzoom();
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const part = <T extends HTMLElement>(root: ParentNode, name: string): T => {
  const element = root.querySelector<T>(`[data-part="${name}"]`);
  if (element === null) {
    throw new Error(`panzoom: no ${name}`);
  }
  return element;
};

const image = (root: ParentNode): HTMLImageElement => part<HTMLImageElement>(root, "panzoom-image");
const value = (root: ParentNode): HTMLElement => part(root, "panzoom-value");
const transform = (root: ParentNode): string => image(root).style.transform;

/** A key on the viewport, as a reader's would arrive. */
const press = async (
  viewport: HTMLElement,
  key: string,
  init: KeyboardEventInit = {},
): Promise<void> => {
  viewport.dispatchEvent(
    new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true, ...init }),
  );
  await settle();
};

const click = async (element: HTMLElement): Promise<void> => {
  element.click();
  await settle();
};

const button = (root: ParentNode, label: string): HTMLButtonElement => {
  const found = [...root.querySelectorAll<HTMLButtonElement>("button")].find(
    (element) => element.textContent?.trim() === label,
  );
  if (found === undefined) {
    throw new Error(`panzoom: no button "${label}"`);
  }
  return found;
};

const pointer = (
  viewport: HTMLElement,
  type: string,
  at: readonly [number, number],
  pointerId = 9,
): void => {
  viewport.dispatchEvent(
    new PointerEvent(type, {
      bubbles: true,
      cancelable: true,
      composed: true,
      pointerId,
      pointerType: "mouse",
      isPrimary: true,
      button: 0,
      buttons: type === "pointerup" ? 0 : 1,
      clientX: at[0],
      clientY: at[1],
    }),
  );
};

/** A point in the viewport, in client coordinates. */
const at = (viewport: HTMLElement, x: number, y: number): [number, number] => {
  const rect = viewport.getBoundingClientRect();
  return [rect.left + x, rect.top + y];
};

describe("Panzoom", () => {
  it("makes the frame a focusable, named viewport with a live value", () => {
    const { root } = mounted();
    const viewport = part(root, "panzoom-viewport");
    const readout = value(root);

    expect(viewport.tabIndex).toBe(0);
    expect(viewport.getAttribute("role")).toBe("group");
    expect(viewport.getAttribute("aria-roledescription")).toBe("zoomable image");
    expect(viewport.getAttribute("aria-label")).toBe("A mountain lake at dusk");
    expect(viewport.getAttribute("aria-describedby")).toBe(readout.id);
    expect(readout.getAttribute("role")).toBe("status");
    expect(readout.getAttribute("aria-live")).toBe("polite");
    expect(readout.textContent).toBe("100%");

    viewport.focus();
    expect(document.activeElement).toBe(viewport);
  });

  it("zooms with + and -, and returns to 100% with 0", async () => {
    const { root } = mounted();
    const viewport = part(root, "panzoom-viewport");

    await press(viewport, "+");
    expect(value(root).textContent).toBe("125%");
    expect(transform(root)).toBe("translate(0px, 0px) scale(1.25)");

    await press(viewport, "-");
    expect(value(root).textContent).toBe("100%");
    // an unhandled key stays the page's
    expect(
      viewport.dispatchEvent(
        new KeyboardEvent("keydown", { key: "Tab", bubbles: true, cancelable: true }),
      ),
    ).toBe(true);

    await press(viewport, "+");
    await press(viewport, "ArrowRight");
    await press(viewport, "0");
    expect(value(root).textContent).toBe("100%");
    expect(transform(root)).toBe("translate(0px, 0px) scale(1)");
  });

  it("pans with the arrows, and clamps at the edge of the frame", async () => {
    const { root } = mounted();
    const viewport = part(root, "panzoom-viewport");
    await press(viewport, "+");
    await press(viewport, "+");

    await press(viewport, "ArrowRight");
    await press(viewport, "ArrowDown");
    expect(transform(root)).toBe("translate(24px, 24px) scale(1.5)");

    // Shift pans four steps at once; 120 px is half the overflow at 1.5, so the second half of it stops at the frame
    await press(viewport, "ArrowRight", { shiftKey: true });
    await press(viewport, "ArrowRight", { shiftKey: true });
    expect(transform(root)).toBe("translate(120px, 24px) scale(1.5)");
  });

  it("resets the scale and the pan on a double click", async () => {
    const { root } = mounted();
    const viewport = part(root, "panzoom-viewport");
    await press(viewport, "+");
    await press(viewport, "+");
    await press(viewport, "ArrowRight");

    viewport.dispatchEvent(new MouseEvent("dblclick", { bubbles: true, cancelable: true }));
    await settle();

    expect(value(root).textContent).toBe("100%");
    expect(transform(root)).toBe("translate(0px, 0px) scale(1)");
  });

  it("pans with a pointer drag and stops when the pointer lifts", async () => {
    const { root } = mounted();
    const viewport = part(root, "panzoom-viewport");
    await click(button(root, "Zoom in"));

    pointer(viewport, "pointerdown", at(viewport, 240, 135));
    pointer(viewport, "pointermove", at(viewport, 260, 145));
    await settle();
    expect(transform(root)).toBe("translate(20px, 10px) scale(1.25)");

    pointer(viewport, "pointerup", at(viewport, 260, 145));
    pointer(viewport, "pointermove", at(viewport, 440, 300));
    await settle();
    expect(transform(root)).toBe("translate(20px, 10px) scale(1.25)");
  });

  it("keeps the image covering the frame, however far it is dragged", async () => {
    const { root } = mounted();
    const viewport = part(root, "panzoom-viewport");
    for (let i = 0; i < 4; i += 1) {
      await click(button(root, "Zoom in"));
    }
    expect(value(root).textContent).toBe("200%");

    pointer(viewport, "pointerdown", at(viewport, 240, 135));
    pointer(viewport, "pointermove", at(viewport, 740, 535));
    await settle();
    // half the scaled overflow: 480 * (2 - 1) / 2 and 270 * (2 - 1) / 2
    expect(transform(root)).toBe("translate(240px, 135px) scale(2)");
    pointer(viewport, "pointerup", at(viewport, 740, 535));
  });

  it("zooms and resets from the controls, with the live value following", async () => {
    const { root } = mounted();
    const zoomIn = button(root, "Zoom in");
    const zoomOut = button(root, "Zoom out");
    const reset = button(root, "Reset");

    await click(zoomIn);
    expect(value(root).textContent).toBe("125%");
    expect(transform(root)).toBe("translate(0px, 0px) scale(1.25)");

    await click(zoomOut);
    expect(value(root).textContent).toBe("100%");

    await click(zoomIn);
    await click(zoomIn);
    expect(value(root).textContent).toBe("150%");
    await click(reset);
    expect(value(root).textContent).toBe("100%");
    expect(transform(root)).toBe("translate(0px, 0px) scale(1)");
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
